/** Paise helpers (INR smallest unit for Razorpay). */
export function effectiveUnitPricePaise(pricePaise: number, discountPercent: number) {
  return Math.floor((pricePaise * (100 - discountPercent)) / 100);
}

export function lineTotalPaise(unitPaise: number, qty: number) {
  return unitPaise * qty;
}

import { pool } from "../db.js";
import { effectiveUnitPricePaise } from "../utils/money.js";

export type ProductRow = {
  id: number;
  name: string;
  slug: string;
  description: string;
  category: string;
  material: string;
  capacity_ml: number | null;
  color: string;
  price_paise: number;
  discount_percent: number;
  stock_qty: number;
  is_active: 0 | 1;
  created_at: Date;
  updated_at: Date;
};

export type ProductListFilters = {
  q?: string;
  category?: string;
  material?: string;
  color?: string;
  minPricePaise?: number;
  maxPricePaise?: number;
  sort?: "newest" | "price_asc" | "price_desc" | "rating";
  page: number;
  pageSize: number;
};

function mapProductListRow(r: Record<string, unknown>) {
  const pricePaise = Number(r.price_paise);
  const discountPercent = Number(r.discount_percent);
  return {
    id: Number(r.id),
    name: String(r.name),
    slug: String(r.slug),
    category: String(r.category),
    material: String(r.material),
    color: String(r.color),
    capacityMl: r.capacity_ml == null ? null : Number(r.capacity_ml),
    pricePaise,
    discountPercent,
    effectivePricePaise: effectiveUnitPricePaise(pricePaise, discountPercent),
    stockQty: Number(r.stock_qty),
    imageUrl: r.image_url ? String(r.image_url) : null,
    avgRating: r.avg_rating == null ? 0 : Number(r.avg_rating),
    reviewCount: Number(r.review_count ?? 0)
  };
}

export async function listProducts(f: ProductListFilters) {
  const offset = (f.page - 1) * f.pageSize;
  const where: string[] = ["p.is_active = 1"];
  const params: unknown[] = [];

  if (f.category) {
    where.push("p.category = ?");
    params.push(f.category);
  }
  if (f.material) {
    where.push("p.material = ?");
    params.push(f.material);
  }
  if (f.color) {
    where.push("p.color = ?");
    params.push(f.color);
  }
  if (f.q?.trim()) {
    where.push("(p.name LIKE ? OR p.description LIKE ?)");
    const like = `%${f.q.trim()}%`;
    params.push(like, like);
  }

  const effExpr = "FLOOR(p.price_paise * (100 - p.discount_percent) / 100)";
  if (f.minPricePaise != null) {
    where.push(`${effExpr} >= ?`);
    params.push(f.minPricePaise);
  }
  if (f.maxPricePaise != null) {
    where.push(`${effExpr} <= ?`);
    params.push(f.maxPricePaise);
  }

  let orderBy = "p.created_at DESC";
  if (f.sort === "price_asc") orderBy = `${effExpr} ASC`;
  if (f.sort === "price_desc") orderBy = `${effExpr} DESC`;
  if (f.sort === "rating") orderBy = "avg_rating DESC, review_count DESC, p.created_at DESC";

  const sql = `
    SELECT
      p.*,
      (
        SELECT pi.url
        FROM product_images pi
        WHERE pi.product_id = p.id
        ORDER BY pi.sort_order ASC, pi.id ASC
        LIMIT 1
      ) AS image_url,
      COALESCE(AVG(r.rating), 0) AS avg_rating,
      COUNT(r.id) AS review_count
    FROM products p
    LEFT JOIN reviews r ON r.product_id = p.id
    WHERE ${where.join(" AND ")}
    GROUP BY p.id
    ORDER BY ${orderBy}
    LIMIT ? OFFSET ?
  `;

  const listParams = [...params, f.pageSize, offset];
  const [rows] = await pool.query(sql, listParams);

  const countSql = `
    SELECT COUNT(*) AS total
    FROM (
      SELECT p.id
      FROM products p
      WHERE ${where.join(" AND ")}
      GROUP BY p.id
    ) t
  `;
  const [countRows] = await pool.query(countSql, params);
  const total = Number((countRows as { total: number }[])[0]?.total ?? 0);

  return {
    items: (rows as Record<string, unknown>[]).map(mapProductListRow),
    total,
    page: f.page,
    pageSize: f.pageSize
  };
}

export async function getProductBySlug(slug: string) {
