  const agg = (reviewAgg as { avg_rating: number; review_count: number }[])[0];

  return {
    id: p.id,
    name: p.name,
    slug: p.slug,
    description: p.description,
    category: p.category,
    material: p.material,
    color: p.color,
    capacityMl: p.capacity_ml,
