export async function buildOrderInvoicePdfStream(orderId: number): Promise<NodeJS.ReadableStream | null> {
  const order = await getOrderAdmin(orderId);
  if (!order) return null;

  const doc = new PDFDocument({ size: "A4", margin: 50 });
  const stream = doc as unknown as PassThrough;

  doc.fontSize(20).text("Bobakuma India", { align: "left" });
  doc.moveDown(0.25);
  doc.fontSize(10).fillColor("#666666").text("Invoice / Order summary", { align: "left" });
  doc.fillColor("#000000");
  doc.moveDown();

  doc.fontSize(12).text(`Order #${order.id}`);
  doc.fontSize(10).text(`Status: ${order.status}`);
  doc.text(`Date: ${new Date(order.createdAt as Date).toISOString()}`);
  doc.moveDown();

  doc.fontSize(11).text("Ship to:", { underline: true });
  doc.fontSize(10);
  doc.text(order.shipping.name);
  doc.text(order.shipping.phone);
  doc.text(`${order.shipping.line1}${order.shipping.line2 ? `, ${order.shipping.line2}` : ""}`);
  doc.text(`${order.shipping.city}, ${order.shipping.state} ${order.shipping.postal}`);
  doc.text(order.shipping.country);
