"use client";

import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import { locales, resources } from "./resources";

const STORAGE = "bobakuma_lang";

export function initI18n() {
  if (i18n.isInitialized) return i18n;
  const saved = typeof window !== "undefined" ? localStorage.getItem(STORAGE) : null;
  const lng = saved && locales.includes(saved as (typeof locales)[number]) ? saved : "en";

  void i18n.use(initReactI18next).init({
    resources: resources as unknown as Record<string, { translation: Record<string, unknown> }>,
    lng,
    fallbackLng: "en",
    interpolation: { escapeValue: false }
  });

  i18n.on("languageChanged", (l) => {
    if (typeof document !== "undefined") document.documentElement.lang = l;
    try {
      localStorage.setItem(STORAGE, l);
    } catch {
      /* ignore */
    }
  });

  return i18n;
}

export function getStoredLocale() {
  if (typeof window === "undefined") return "en";
  const saved = localStorage.getItem(STORAGE);
  if (saved && locales.includes(saved as (typeof locales)[number])) return saved;
  return "en";
}

