type ListRes = {
  items: Array<{
    id: number;
    name: string;
    slug: string;
    category: string;
    material: string;
    color: string;
    effectivePricePaise: number;
    discountPercent: number;
    imageUrl: string | null;
    avgRating: number;
  }>;
  total: number;
  page: number;
  pageSize: number;
};

function buildQuery(sp: Record<string, string | string[] | undefined>) {
  const p = new URLSearchParams();
  const set = (k: string, v: string | string[] | undefined) => {
    if (!v) return;
    p.set(k, Array.isArray(v) ? v[0] : v);
  };
  set("q", sp.q);
  set("category", sp.category);
  set("material", sp.material);
  set("color", sp.color);
  set("minPrice", sp.minPrice);
  set("maxPrice", sp.maxPrice);
  set("sort", sp.sort);
  set("page", sp.page);
  p.set("pageSize", "12");
  return p.toString();
}

